import{_ as t,o as r,c as o,ah as a}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Higher education: programmes, curricula and promotions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/enseignement-superieur.md","filePath":"src/en/guide/admin/enseignement-superieur.md"}'),s={name:"en/guide/admin/enseignement-superieur.md"};function n(i,e,l,h,c,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="higher-education-programmes-curricula-and-promotions" tabindex="-1">Higher education: programmes, curricula and promotions <a class="header-anchor" href="#higher-education-programmes-curricula-and-promotions" aria-label="Permalink to &quot;Higher education: programmes, curricula and promotions&quot;">​</a></h1><p>If your school awards higher education degrees (bachelor, master, doctorate), ERA organises them along the LMD system: <strong>programmes</strong>, taught at some <strong>levels</strong> (L1, L2, L3…), whose <strong>curriculum</strong> spreads credits across <strong>teaching units (UE)</strong> made of <strong>course elements (EC)</strong>.</p><p>The space opens from <strong>Higher ed. → Programmes</strong>. It appears when your licence includes higher education.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Programmes live in a <strong>department of type &quot;University&quot;</strong>, with its levels. Create them first in school setup:</p><ol><li><strong>School setup → Departments</strong>: a <em>University</em> department, for instance &quot;Faculty of Science&quot;.</li><li><strong>School setup → Levels</strong>: its levels, in order (L1, L2, L3, M1, M2).</li></ol><h2 id="creating-a-programme" tabindex="-1">Creating a programme <a class="header-anchor" href="#creating-a-programme" aria-label="Permalink to &quot;Creating a programme&quot;">​</a></h2><p>From <strong>Programmes</strong>, the <strong>New programme</strong> button asks for:</p><ul><li>the <strong>department</strong> and the programme&#39;s <strong>name</strong>, with an optional code (&quot;INFO&quot;);</li><li>the <strong>degree</strong>: bachelor, master or doctorate;</li><li>the <strong>rhythm</strong>: semesters by default, terms or yearly;</li><li>the <strong>credits a year</strong>, 60 by default. They are shared equally between periods: 30 a semester on semesters;</li><li>the <strong>levels taught</strong>: L1 to L3 for a bachelor, L3 alone for a professional bachelor;</li><li>its <strong>programme heads</strong>.</li></ul><p>The rhythm and department can no longer change once the curriculum has started, and a programme that already has a curriculum or promotions cannot be deleted.</p><h2 id="programme-heads" tabindex="-1">Programme heads <a class="header-anchor" href="#programme-heads" aria-label="Permalink to &quot;Programme heads&quot;">​</a></h2><p>A programme head maintains <strong>their</strong> programme&#39;s curriculum, and that one only. It is not a separate role: a teacher or staff member keeps their usual role and also gets the <strong>Higher ed.</strong> space, limited to the programmes they head. Creating and editing programmes stays with the administrator.</p><h2 id="building-the-curriculum" tabindex="-1">Building the curriculum <a class="header-anchor" href="#building-the-curriculum" aria-label="Permalink to &quot;Building the curriculum&quot;">​</a></h2><p>A programme&#39;s <strong>Curriculum</strong> button opens its curriculum for one academic year, chosen at the top of the page. It is laid out level by level, then period by period.</p><ol><li><strong>Add a unit</strong> in the chosen period: a name, an optional code, and whether it is <strong>elective</strong> (offered as a choice).</li><li>In the unit, <strong>Add an element</strong>: its name, its <strong>credits</strong>, its <strong>coefficient</strong> (equal to the credits by default) and its lecture, tutorial and practical hours.</li></ol><p>Credits are carried by the elements: a unit&#39;s credits are the sum of its elements&#39;, so the two can never disagree.</p><p>An <strong>elective</strong> unit is a choice, among a few or freely within the period&#39;s offer: its credits <strong>complete</strong> the mandatory units&#39; up to the period&#39;s total. With 24 mandatory credits, each student picks 6 credits of electives to reach 30.</p><div class="tip custom-block"><p class="custom-block-title">The credits counter</p><p>Each period shows its credits against what it should carry. Without electives, for instance <strong>28 / 30 credits</strong>. With electives, <strong>24 / 30 mandatory credits</strong>, followed by what is left to complete and the credits on offer: &quot;6 to complete with electives, out of 12 credits on offer&quot;. The counter turns green when the offer can add up.</p></div><p>The arrows reorder a period&#39;s units and a unit&#39;s elements.</p><h2 id="one-curriculum-per-year" tabindex="-1">One curriculum per year <a class="header-anchor" href="#one-curriculum-per-year" aria-label="Permalink to &quot;One curriculum per year&quot;">​</a></h2><p>Each academic year has its own curriculum. Changing this year&#39;s never changes what an earlier promotion followed.</p><p>A new year starts empty. ERA then offers to <strong>start from the previous year&#39;s curriculum</strong> in one click: it is copied as it was, and you adjust it. The old one stays untouched, and a year that already has a curriculum is never overwritten.</p><p>When a school year is <strong>closed</strong>, its curriculum is too: it can still be read but no longer changed.</p><h2 id="promotions" tabindex="-1">Promotions <a class="header-anchor" href="#promotions" aria-label="Permalink to &quot;Promotions&quot;">​</a></h2><p>A <strong>promotion</strong> (for instance &quot;L1 Computing 2026-2027&quot;) is a class of a university department. When you create a class in such a department, ERA asks for the <strong>programme</strong> it follows, then its <strong>level</strong>, chosen among the programme&#39;s.</p><p>A promotion has no bulletins, no year-end decisions and no bulk re-enrolment: those school screens leave it out. Its students will progress on their credits, validated by the programme&#39;s jury.</p><p>Students join it through an <a href="/era-guide/en/guide/secretariat/candidatures.html#a-university-application">application</a> naming the programme and the level.</p><h2 id="pedagogical-registration" tabindex="-1">Pedagogical registration <a class="header-anchor" href="#pedagogical-registration" aria-label="Permalink to &quot;Pedagogical registration&quot;">​</a></h2><p>A programme&#39;s <strong>Promotions</strong> button lists its promotions for the chosen year, with their headcount. A promotion whose level has no curriculum yet for that year is flagged.</p><p><strong>Pedagogical registration</strong> opens a promotion&#39;s page:</p><ul><li>at the top, its units period by period, mandatory and elective;</li><li>below, its students, with their credits for each period and the elective units they chose.</li></ul><p>Every student takes <strong>all the mandatory units</strong> of their level: nothing to enter for them, and a unit added to the curriculum applies to the whole promotion. Their <strong>elective units</strong> are chosen with the <strong>Electives</strong> button on their row: tick the ones they take, then save. They complete each period&#39;s credits: the window shows what is left to choose, and ERA refuses a choice that goes past the total. In the list, a complete period shows in green, for instance <strong>30 / 30 credits</strong>.</p><p>The administrator and the programme&#39;s heads keep these registrations. Once the year is closed, they no longer change.</p>',33)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
